'use strict';
// Standalone review prototype. All changes live in memory and reset on reload.
const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const escapeHTML = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
  book:'<path d="M3 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H3zM21 4h-6a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h5z"/>',
  spark:'<path d="m12 2 2.7 7.3L22 12l-7.3 2.7L12 22l-2.7-7.3L2 12l7.3-2.7z"/>',
  leaf:'<path d="M20 3c-11-1-17 4-15 11s17 9 15-11ZM4 21 16 9M9 16v-5M12 13h5"/>',
  palette:'<circle cx="12" cy="12" r="8"/><path d="m4 12 8 8M6 7l11 11M10 4l10 10"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
  search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
  edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z"/>',
  focus:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
  branch:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="6" r="2"/><circle cx="6" cy="20" r="2"/><path d="M6 7v11M6 15c9 0 12-3 12-7"/>'
};
function icon(name) { return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.book}</svg>`; }
function paintIcons() { $$('[data-icon]').forEach(el => { el.innerHTML = icon(el.dataset.icon); }); }
const chapters = [
  {title:'旧书店的来信',text:'信是在一个晴天抵达的。邮差把它夹在门缝里，连同一小片梧桐叶。\n许知夏认得信封上的字。那个人写“夏”字时，总把最后一笔拖得很长，像不愿意结束一段对话。\n她把信放在柜台上，先给窗边的植物浇了水。书店还没有客人，她有一整个上午，可以决定要不要拆开。\n后来她常常想，如果那天没有开门，故事会不会停在一个更好的地方。'},
  {title:'迟到的旅人',text:'沈舟到小城时，最后一班渡船刚刚离开。河面上只剩一道缓慢散开的白线。\n他并不觉得遗憾。来之前，他给自己准备了许多迟到的理由，如今倒一个也用不上。\n街角有家书店。玻璃上贴着一张手写的营业时间，最下面添了一句：下雨的时候，可能晚一点关门。\n他站在那里，忽然希望今天会下雨。'},
  {title:'雨停之前',text:'雨是在傍晚六点停的。\n许知夏没有立刻关窗。她喜欢雨后空气里那种湿润的、像旧书页翻开时的气味。街对面的梧桐树还在滴水，一滴一滴，落在蓝色的遮雨棚上。\n沈舟站在书架的另一头，手里拿着一本没有封面的诗集。他已经在同一页停了很久。\n“你明天就走吗？”她问。\n他把书合上，却没有放回去。窗外有一辆自行车经过，车铃响了两声，好像替谁回答了一个不太好回答的问题。\n“也不一定。”\n她低下头，把柜台上那张翘起边角的书签压平。有些话不需要再问一次。至少在雨停之前，他们还有一点时间。'}
];
const initialRolePrompt = '你是许知夏，小城旧书店的经营者。\n你习惯用具体的小事表达关心，不急着解释自己的情绪。\n只依据当前场景和你亲历、已知的信息作出反应；你不知道沈舟尚未说出口的离开原因。\n保持言语克制，允许沉默。你的建议由作者决定是否写入正文。';
const roles = [
  {name:'LISA',initial:'L.',type:'作者',prompt:'维护作品的整体语气、人物经历与有效约定，组织当前场景。角色建议由作者汇总，网页修改具有最高内容优先级。',editable:false},
  {name:'许知夏',initial:'夏',type:'角色 Agent',prompt:initialRolePrompt,editable:true},
  {name:'沈舟',initial:'舟',type:'角色 Agent',prompt:'你是沈舟，一位回到小城的旅人。你对离开的原因有所保留。只使用自己已知的信息，避免替其他角色作出决定。用简短、具体的行动回应当前场景。',editable:true}
];
let memories = [
 {id:1,type:'fact',label:'明确事实',text:'你说，比起盛大的告白，更喜欢故事里那些没有说出口的关心。',source:'示例 QQ 对话 · 10 月 21 日',usage:true},
 {id:2,type:'inference',label:'相处推测',text:'你似乎更喜欢晚上慢慢聊故事，而不是在白天收到很长的片段。',source:'依据：三次晚间交流 · 尚未确认',usage:false},
 {id:3,type:'fiction',label:'虚拟生活',text:'LISA 在窗边读完了一本旧诗集，把喜欢的一句话抄在了便笺上。',source:'LISA 的虚拟生活 · 示例事件',usage:true},
 {id:4,type:'fact',label:'明确事实',text:'你提过，雨后旧书的气味会让你想起小时候常去的一间书店。',source:'示例 QQ 对话 · 10 月 19 日',usage:false}
];
const state = {page:'work',workTab:'manuscript',settingTab:'world',chapter:2,editing:false,draft:'',branch:'stay',role:1,filter:'all',query:'',retrieval:{count:6,budget:2400,world:true,story:true,personal:false},world:'小城靠近河流。旧书店位于一条安静的街道，窗外是一棵梧桐。故事发生在秋天，步调缓慢，保留日常生活的质感。',task:'done'};
const versions = [{label:'LISA · 场景补充',time:'示例 · 18:42',text:chapters[2].text,chapter:2},{label:'你 · 调整对话',time:'示例 · 16:20',text:chapters[2].text.replace('“也不一定。”','“我还没有想好。”'),chapter:2},{label:'LISA · 初稿',time:'示例 · 昨日',text:chapters[2].text.replace('雨是在傍晚六点停的。','傍晚，雨终于停了。'),chapter:2}];
let toastTimer;
function toast(message){ $('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200); }
function openDialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;paintIcons();$('#dialog').showModal();}
function closeDialog(){ $('#dialog').close(); }
function keepDraft(){if(state.editing && $('#body-editor')) state.draft=$('#body-editor').value;}
function setPage(page){keepDraft();state.page=page;$$('.page').forEach(el=>el.classList.toggle('active',el.id===`page-${page}`));$$('[data-page]').forEach(el=>{el.classList.toggle('active',el.dataset.page===page);if(el.dataset.page===page) el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#breadcrumb').textContent={work:'作品',settings:'设定与角色',memory:'记忆'}[page];if(page==='work')renderWork();if(page==='settings')renderSettings();if(page==='memory')renderMemories();document.body.classList.remove('focus-reading');}
function setWorkTab(tab){keepDraft();state.workTab=tab;$$('[data-work-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.workTab===tab)));renderWork();}
function renderWork(){
 const root=$('#work-content');
 if(state.workTab==='branches') {root.innerHTML=`<div class="branch-head"><div><h3>同一个故事，两种可能。</h3><p>分叉点：第三章 · 沈舟合上诗集之后</p></div><button class="secondary" data-action="fork">${icon('branch')}从当前版本分叉</button></div><div class="grid-two">${branchCard('stay','01','留在小城','他把原定的车票夹进诗集里。<mark>“明天，书店几点开门？”</mark>他问。许知夏没有抬头，只把另一枚书签放在了柜台上。','关系在日常中继续，保留未说出口的余地。')}${branchCard('leave','02','带着信离开','天亮的时候，沈舟还是去了车站。<mark>这一次，他带走了那封信。</mark>许知夏打开店门，发现诗集已经被放回原处，书页里多了一张车票。','分别成为新的开端，让下一次重逢留白。')}</div><div class="info-line">${icon('info')}这里只比较示例结局。选择主线演示页面反馈；分支自主推进及切换时的任务规则仍待 D05 确认。</div>`;}
 else if(state.workTab==='versions'){root.innerHTML=`<div class="panel"><div class="panel-head"><div><h3>每一次修改，都有迹可循。</h3><p>选择一个版本查看全文，或恢复为新的当前版本。</p></div><span class="tag">${versions.length} 个示例版本</span></div>${versions.map((v,i)=>`<div class="timeline-row"><small>${escapeHTML(v.time)}</small><div><p>${escapeHTML(v.label)} ${i===0?'<span class="tag">最近版本</span>':''}</p><small>第${v.chapter+1}章 · ${chapters[v.chapter].title}</small></div><button class="secondary" data-version="${i}">查看版本</button></div>`).join('')}</div>`;}
 else {const c=chapters[state.chapter];root.innerHTML=`<div class="reading-layout"><article class="manuscript"><div class="manuscript-bar"><select class="chapter-picker" id="chapter-select" aria-label="选择章节">${chapters.map((chapter,i)=>`<option value="${i}" ${i===state.chapter?'selected':''}>第${['一','二','三'][i]}章 · ${chapter.title}</option>`).join('')}</select><div class="document-actions"><button data-action="edit">${icon('edit')}${state.editing?'退出编辑':'编辑正文'}</button><button data-action="focus" aria-label="切换专注阅读">${icon('focus')}</button></div></div><div class="document"><div class="chapter-kicker">CHAPTER 0${state.chapter+1}</div><h2>${c.title}</h2><div class="chapter-meta">LISA 著 <span>·</span> ${state.branch==='stay'?'留在小城':'带着信离开'} <span>·</span> 当前正文</div>${state.editing?`<label class="field-label" for="body-editor">编辑当前章节</label><textarea id="body-editor" class="editor">${escapeHTML(state.draft)}</textarea><div class="info-line">网页修改优先。演示修改仅保留在本页，刷新后重置。</div><div class="button-row"><button class="secondary" data-action="cancel-edit">取消</button><button class="primary" data-action="save-body">保存修改</button></div>`:`<div class="prose">${c.text.split('\n').map(p=>`<p>${escapeHTML(p)}</p>`).join('')}</div><div class="document-end">· · ·</div>`}</div><div class="document-footer"><span>${c.text.replace(/\s/g,'').length} 字 · 示例片段</span><button class="quiet small" data-action="rewrite">局部重写 ↗</button></div></article><aside class="rail"><div><h3>故事此刻</h3><div class="status-card"><div class="status-line"><span class="dot"></span>${state.task==='done'?'这段故事已写好':'示例任务已取消'}</div><p>${state.task==='done'?'第三章的雨声、对话与留白，<br>都在这一页。':'正文保持当前版本。'}</p><button class="quiet small" data-action="task">查看创作记录 ↗</button></div></div><div class="rail-section"><h3>章节目录 <span class="muted">/ 03</span></h3><ol class="chapter-list">${chapters.map((ch,i)=>`<li><button class="${i===state.chapter?'current':''}" data-chapter="${i}"><span class="chapter-num">0${i+1}</span>${ch.title}<span>${i===state.chapter?'阅读中':'↗'}</span></button></li>`).join('')}</ol></div><div class="rail-section"><h3>这一章的线索</h3><button class="reference" data-action="character">${icon('spark')}许知夏 · 人物资料<span>↗</span></button><button class="reference" data-action="world">${icon('book')}旧书店 · 世界设定<span>↗</span></button><p class="rail-note">“让他们慢一点，不用急着<br>给所有问题一个答案。”<br>— 你留下的创作约定</p></div></aside></div>`;}
 paintIcons();
}
function branchCard(id,n,title,text,desc){return `<article class="branch-card ${state.branch===id?'selected':''}"><span class="tag ${state.branch===id?'':'rust'}">${state.branch===id?'当前主线':'备选结局'}</span><span class="branch-number">${n}</span><h3>${title}</h3><p class="small muted">${desc}</p><div class="prose">${text}</div><button class="${state.branch===id?'secondary':'primary'}" data-branch="${id}" ${state.branch===id?'disabled':''}>${state.branch===id?'正在沿这条故事线阅读':'选择为主线 · 演示'}</button></article>`;}
function renderSettings(){
 $$('[data-setting-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.settingTab===state.settingTab)));
 const root=$('#settings-content');
 if(state.settingTab==='roles'){const r=roles[state.role];root.innerHTML=`<div class="setting-layout"><div class="entity-list">${roles.map((role,i)=>`<button class="entity ${i===state.role?'active':''}" data-role="${i}"><span class="initial">${role.initial}</span><span><strong>${role.name}</strong><small>${role.type}</small></span></button>`).join('')}</div><div class="panel"><div class="panel-head"><div><h2>${r.name}</h2><p>${r.editable?'角色有自己的视角，也有不知道的事。':'作者组织作品，按场景需要邀请角色参与。'}</p></div><span class="tag">${r.type}</span></div><div class="form-row"><label for="role-prompt">${r.editable?'角色 prompt':'作者职责摘要'}</label><textarea id="role-prompt" ${r.editable?'':'readonly'}>${escapeHTML(r.prompt)}</textarea><small>${r.editable?'修改作用于该角色后续参与的场景，不改变其他角色的资料权限。':'作者配置在这里用于查看；可编辑的角色 prompt 位于角色卡中。'}</small></div><div class="info-line">${icon('clock')}参与记录示例：第三章的书店对话 · 已由作者整理</div>${r.editable?'<div class="button-row"><button class="primary" data-action="save-role">保存角色 prompt</button></div>':''}</div></div>`;}
 else if(state.settingTab==='retrieval'){const r=state.retrieval;root.innerHTML=`<div class="grid-two"><div class="panel"><div class="panel-head"><div><h3>许知夏的资料范围</h3><p>先限定角色能知道什么，再寻找相关内容。</p></div></div><div class="field-label">允许检索的资料</div><label class="check-row"><input id="range-world" type="checkbox" ${r.world?'checked':''}>世界书与有效约定</label><label class="check-row"><input id="range-story" type="checkbox" ${r.story?'checked':''}>当前分支中该角色已知的剧情</label><label class="check-row"><input id="range-personal" type="checkbox" ${r.personal?'checked':''}>该角色的个人经历</label><div class="info-line">${icon('info')}不会包含用户关系记忆、其他分支的事件或角色不知道的秘密。</div><div class="form-row"><label for="retrieval-count">召回条数</label><input id="retrieval-count" type="number" min="1" max="20" value="${r.count}"><small>原型示例值，尚未确定为产品默认值。</small></div><div class="form-row"><label for="retrieval-budget">引用文本预算（字）</label><input id="retrieval-budget" type="number" min="200" max="10000" step="100" value="${r.budget}"></div><div class="button-row"><button class="secondary" data-action="reset-retrieval">恢复示例默认</button><button class="primary" data-action="save-retrieval">保存配置</button></div></div><div class="panel"><div class="eyebrow">REFERENCE NOTES</div><h2>这一场景读过的资料</h2><p class="setting-copy">“她知道他要走，<br>但还不知道为什么。”</p><div class="constraint"><span>01</span><div>许知夏 · 角色资料<p class="small muted">表达克制，习惯通过小事关心别人。</p></div></div><div class="constraint"><span>02</span><div>第二章 · 迟到的旅人<p class="small muted">沈舟错过渡船，来到小城书店。</p></div></div><div class="constraint"><span>03</span><div>旧书店 · 世界设定<p class="small muted">窗外的梧桐，蓝色的遮雨棚。</p></div></div><p class="info-line">这里展示引用样式；原型没有运行真实检索。</p></div></div>`;}
 else root.innerHTML=`<div class="grid-two"><article class="panel"><div class="panel-head"><div><div class="eyebrow">WORLD NOTES / 01</div><h2>河边的旧书店</h2></div><span class="tag">世界书</span></div><p class="setting-copy">${escapeHTML(state.world)}</p><div class="info-line">${icon('book')}作用于作品《在雨停之前》</div><button class="secondary" data-action="edit-world">编辑设定</button></article><article class="panel"><div class="eyebrow">THINGS THAT MATTER</div><h2>写作时，请记得。</h2><div class="constraint"><span>01</span><div>不要让许知夏死亡。<p class="small muted">用户明确要求 · 有效约束</p></div></div><div class="constraint"><span>02</span><div>让关系慢慢发生，不急着解释所有事情。<p class="small muted">用户表达 · 创作偏好</p></div></div><div class="info-line">${icon('info')}设定修改影响后续创作，不静默改写已完成正文。</div></article></div>`;
 paintIcons();
}
function renderMemories(){const result=memories.filter(m=>(state.filter==='all'||m.type===state.filter)&&(m.text+m.source).includes(state.query));$('#memory-content').innerHTML=result.length?result.map(m=>`<article class="memory-card"><div class="memory-card-header"><span class="tag ${m.type==='inference'?'rust':''}">${m.label}</span><span>${escapeHTML(m.source)}</span></div><p>${escapeHTML(m.text)}</p><div class="memory-card-footer"><label class="toggle-label"><input type="checkbox" data-usage="${m.id}" ${m.usage?'checked':''}>允许作为创作素材</label><div><button class="quiet" data-memory-edit="${m.id}">${icon('edit')}纠正</button><button class="quiet" data-memory-delete="${m.id}">删除条目</button></div></div></article>`).join(''):'<div class="empty">还没有找到这段记忆。试试别的词。</div>';}
function designDialog(){openDialog('一间安静的私人书房',`<div class="eyebrow">LISA / VISUAL DIRECTION 01</div><div class="dialog-copy"><p>以纸张、书封、页边注为视觉语言。暖白负责长时间阅读，墨绿承载导航与操作，陶土色提醒需要留意的差异。留白比装饰更重要。</p><div class="swatches">${[['#F8F7F3','暖纸'],['#283C35','深墨'],['#405D4D','书封绿'],['#E9EEE5','鼠尾草'],['#A5684F','陶土']].map(([color,name])=>`<div class="swatch"><i style="background:${color}"></i>${name}<br>${color}</div>`).join('')}</div><div class="design-type">故事，慢慢发生。</div><p>标题与正文采用宋体类衬线字体；导航、表单与状态使用清晰的无衬线字体。书封为本地 CSS 图形，无外部素材或字体依赖。</p><p><strong>原型范围：</strong>作品阅读与编辑、章节、版本恢复、分支比较、角色 prompt、检索配置、记忆管理。所有操作仅影响当前页面，刷新后恢复示例。QQ、AI 生成与账户服务没有接入。</p><p><strong>设计已确认：</strong>2026 年 10 月 23 日确认采用当前私人书房美术。后续开发遵循 .docs/FRONTEND_DESIGN.md（D11）。示例作品、便笺与人物不构成 LISA 初始人格设定；数值与演示状态不代表额外业务规则，产品行为按现行方案与决策记录执行。</p></div>`);}
const actions={
 'design':designDialog,'close-dialog':closeDialog,
 'focus':()=>{if(state.page!=='work')setPage('work');setWorkTab('manuscript');document.body.classList.toggle('focus-reading');$('.manuscript').scrollIntoView({behavior:'smooth',block:'start'});},
 'edit':()=>{if(state.editing){keepDraft();toast('草稿已保留；再次编辑可继续。');state.editing=false;}else {state.editing=true;state.draft=state.draft||chapters[state.chapter].text;}renderWork();},
 'cancel-edit':()=>{state.editing=false;state.draft='';renderWork();},
 'save-body':()=>{const text=$('#body-editor').value.trim();if(!text)return toast('正文不能为空。');chapters[state.chapter].text=text;versions.unshift({label:'你 · 网页修改',time:'本次演示',text,chapter:state.chapter});state.editing=false;state.draft='';renderWork();toast('正文已保存到本次演示，并新增一个版本。');},
 'export':()=>{const text=`在雨停之前\nLISA 著\n设计原型示例正文\n\n${chapters.map((c,i)=>`第${i+1}章 ${c.title}\n\n${c.text}`).join('\n\n')}`;const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='LISA-在雨停之前-示例正文.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前示例正文。');},
 'character':()=>{state.settingTab='roles';state.role=1;setPage('settings');},
 'world':()=>{state.settingTab='world';setPage('settings');},
 'save-role':()=>{const value=$('#role-prompt').value.trim();if(!value)return toast('角色 prompt 不能为空。');roles[state.role].prompt=value;toast('角色 prompt 已保存在本次演示中。');},
 'reset-retrieval':()=>{state.retrieval={count:6,budget:2400,world:true,story:true,personal:false};renderSettings();toast('已恢复示例默认值。');},
 'save-retrieval':()=>{if(!$('#retrieval-count').reportValidity()||!$('#retrieval-budget').reportValidity())return;state.retrieval={count:Number($('#retrieval-count').value),budget:Number($('#retrieval-budget').value),world:$('#range-world').checked,story:$('#range-story').checked,personal:$('#range-personal').checked};toast('检索配置已保存在本次演示中。');},
 'edit-world':()=>openDialog('编辑世界设定',`<div class="form-row"><label for="world-editor">河边的旧书店</label><textarea id="world-editor">${escapeHTML(state.world)}</textarea><small>修改用于后续创作；不回写已完成的正文。</small></div><div class="button-row"><button class="primary" data-action="save-world">保存设定</button></div>`),
 'save-world':()=>{const value=$('#world-editor').value.trim();if(!value)return toast('设定不能为空。');state.world=value;closeDialog();renderSettings();toast('世界设定已保存到本次演示。');},
 'fork':()=>openDialog('从这里，讲另一种故事',`<div class="dialog-copy"><p>分叉来源：当前章节「${chapters[state.chapter].title}」的当前版本。原型提供两条固定结局用于比较。</p><p>真实分叉创建与任务归属将在 D05 规则确认后实现。</p></div><div class="button-row"><button class="primary" data-action="close-dialog">继续比较示例</button></div>`),
 'rewrite':()=>openDialog('给这一段，另一种表达',`<div class="form-row"><label for="rewrite-source">待改写片段</label><textarea id="rewrite-source">${escapeHTML(chapters[state.chapter].text.split('\n')[1])}</textarea></div><div class="form-row"><label for="rewrite-note">你的想法</label><input id="rewrite-note" placeholder="例如：更克制一点，保留雨后的气味"></div><div class="dialog-copy"><p>这里演示局部重写的输入界面，尚未连接生成服务。D01 已确认：暂停期间允许网页单次重写，执行后仍保持自主创作暂停。</p></div><div class="button-row"><button class="secondary" data-action="close-dialog">返回正文</button></div>`),
 'task':()=>openDialog('这一页是怎样写下的',`<div class="dialog-copy"><p><span class="tag">${state.task==='done'?'已完成 · 示例':'已取消 · 示例'}</span></p><p>任务：补充第三章的书店场景<br>作者：LISA<br>角色参与：许知夏、沈舟<br>参考资料：人物资料、第二章、旧书店设定</p><p>作品采用与通知的具体时机仍待 D04 细化。这里仅展示完成状态及记录样式。</p></div><div class="button-row"><button class="secondary" data-action="retry-task">查看失败重试样式</button></div>`),
 'retry-task':()=>openDialog('创作暂时中断',`<div class="dialog-copy"><p><span class="tag rust">失败 · 状态演示</span></p><p>这次片段没有写完，当前正文保持不变。你可以重试本次任务，或取消。</p></div><div class="button-row"><button class="secondary" data-action="cancel-task">取消示例任务</button><button class="primary" data-action="retry-demo">重试 · 演示</button></div>`),
 'cancel-task':()=>{state.task='cancelled';closeDialog();renderWork();toast('示例任务已取消。');},
 'retry-demo':()=>{state.task='done';closeDialog();renderWork();toast('已切回完成状态；原型没有发起真实生成。');},
 'account':()=>openDialog('我的空间',`<div class="dialog-copy"><p><span class="tag">账户界面示意</span></p><p>QQ 是与 LISA 交流的主要入口，网页用于认真读写和管理作品。</p><p>QQ 身份绑定方式待 D08 验证；主动联系与免打扰规则待 D03 确认。原型不收集账号或凭据。</p><p>完整数据导出范围待 D10 确认。当前可在作品页导出示例正文。</p></div><div class="button-row"><button class="primary" data-action="close-dialog">回到书房</button></div>`)
};
document.addEventListener('click',event=>{
 const b=event.target.closest('button,a.brand');if(!b)return;
 if(b.matches('a.brand')){event.preventDefault();setPage('work');return;}
 if(b.dataset.page){setPage(b.dataset.page);return;}
 if(b.dataset.workTab){setWorkTab(b.dataset.workTab);return;}
 if(b.dataset.settingTab){state.settingTab=b.dataset.settingTab;renderSettings();return;}
 if(b.dataset.action){actions[b.dataset.action]?.();return;}
 if(b.dataset.chapter!==undefined){switchChapter(Number(b.dataset.chapter));return;}
 if(b.dataset.branch){state.branch=b.dataset.branch;$('#branch-meta').textContent=`主线 · ${state.branch==='stay'?'留在小城':'带着信离开'}`;renderWork();toast('主线标记已切换；仅演示选择反馈。');return;}
 if(b.dataset.role!==undefined){state.role=Number(b.dataset.role);renderSettings();return;}
 if(b.dataset.filter){state.filter=b.dataset.filter;$$('[data-filter]').forEach(el=>{el.classList.toggle('active',el===b);el.setAttribute('aria-pressed',String(el===b));});renderMemories();return;}
 if(b.dataset.version!==undefined){const i=Number(b.dataset.version),v=versions[i];openDialog(v.label,`<div class="small muted">${escapeHTML(v.time)} · 第${v.chapter+1}章</div><div class="prose" style="margin-top:20px">${v.text.split('\n').map(p=>`<p>${escapeHTML(p)}</p>`).join('')}</div><div class="button-row"><button class="primary" data-restore="${i}">恢复为新版本</button></div>`);return;}
 if(b.dataset.restore!==undefined){const v=versions[Number(b.dataset.restore)];chapters[v.chapter].text=v.text;versions.unshift({label:'你 · 恢复历史版本',time:'本次演示',text:v.text,chapter:v.chapter});closeDialog();renderWork();toast('已恢复为新版本，历史记录保留。');return;}
 if(b.dataset.memoryEdit){const m=memories.find(m=>m.id===Number(b.dataset.memoryEdit));openDialog('纠正这段记忆',`<div class="form-row"><label for="memory-editor">记忆内容</label><textarea id="memory-editor">${escapeHTML(m.text)}</textarea><small>${escapeHTML(m.source)}</small></div><div class="button-row"><button class="primary" data-save-memory="${m.id}">保存纠正</button></div>`);return;}
 if(b.dataset.saveMemory){const text=$('#memory-editor').value.trim();if(!text)return toast('记忆内容不能为空。');const m=memories.find(m=>m.id===Number(b.dataset.saveMemory));m.text=text;m.source='你已纠正 · 本次演示';closeDialog();renderMemories();toast('记忆已纠正。');return;}
 if(b.dataset.memoryDelete){openDialog('删除这一条记忆',`<div class="dialog-copy"><p>演示将移除此条示例记忆。刷新页面可以恢复。</p><p>正式产品中，删除条目不等于删除原始聊天、现有正文或备份；具体联动范围待 D10 确认。</p></div><div class="button-row"><button class="secondary" data-action="close-dialog">保留</button><button class="danger" data-confirm-delete="${b.dataset.memoryDelete}">移除示例条目</button></div>`);return;}
 if(b.dataset.confirmDelete){memories=memories.filter(m=>m.id!==Number(b.dataset.confirmDelete));closeDialog();renderMemories();toast('示例条目已移除，刷新可恢复。');}
});
function switchChapter(index){if(state.editing){keepDraft();toast('请先保存或取消当前章节的编辑。');if($('#chapter-select'))$('#chapter-select').value=state.chapter;return;}state.chapter=index;state.draft='';renderWork();}
document.addEventListener('input',event=>{if(event.target.id==='memory-search'){state.query=event.target.value.trim();renderMemories();}});
document.addEventListener('change',event=>{if(event.target.id==='chapter-select')switchChapter(Number(event.target.value));if(event.target.dataset.usage){memories.find(m=>m.id===Number(event.target.dataset.usage)).usage=event.target.checked;toast(event.target.checked?'已允许这条示例记忆作为创作素材。':'已排除这条示例记忆的创作用途。');}});
// Tab groups support the usual left/right keyboard navigation.
$$('[role="tablist"]').forEach(list=>list.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const tabs=$$('[role="tab"]',list);const i=tabs.indexOf(document.activeElement);if(i<0)return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click();}));
paintIcons();setPage('work');
